  const lc = s => String(s == null ? '' : s).toLowerCase();
  const N = 5;
  const inGrid = (x, y) => x >= 0 && y >= 0 && x < N && y < N && !((x === 0 || x === N - 1) && (y === 0 || y === N - 1));
  const CELLS = []; for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) if (inGrid(x, y)) CELLS.push([x, y]);
  const key = (x, y) => x + ',' + y;

  const RUNES = ['ᚠᛉᛜ', 'ᚨᛁᛒᚠᚹ', 'ᚷᛈᛚᚨᛁ', 'ᚾᛏᛟᚷᛈ', 'ᛗᚦᚾ'];
  const runeAt = (x, y) => { const r = RUNES[y]; return r ? [...r][y === 0 || y === N - 1 ? x - 1 : x] || '' : ''; };

  const shapes = () => Object.values(ctx.gd().bases || {}).filter(b => b.Slot === 'Idol')
    .map(b => ({ id: lc(b.Id), name: b.Name, w: b.Width || 1, h: b.Height || 1 }))
    .sort((a, b) => b.w * b.h - a.w * a.h || b.w - a.w);
  const shape = id => shapes().find(s => s.id === id);
  const sizeText = s => s.w + 'x' + s.h;


  const F = { idols: [], sel: null, msg: '', alt: null, charId: '' }; // idol: { uid, base, label, x, y, uniq } (uniq: the unique's id, for its own picture)
  let nextUid = 1;
