    if (!isKw && !ctx.tip) return hideTip();
    let html = ''; try { html = isKw ? kwTip(t.dataset.kw) : ctx.tip(key.slice(0, i), key.slice(i + 1)); } catch (err) { html = ''; }
    if (!html) return hideTip();
