    const GD = ctx.gd();
    let h = '<div class="cmp-intro"><div class="eyebrow">REFERENCE</div><h2>Skill Scaling</h2><p>What each skill does as its gem levels up. The colour is the gem\'s: red Strength, green Dexterity, blue Intelligence.</p></div>';
    if (!GD || !GD.skills || !GD.scaling || !GD.scaling.Gem) { el.innerHTML = h + '<div class="card"><p class="hint">Load the game data first.</p></div>'; return; }
    const G = GD.scaling.Gem, max = G.MaxLevel || 20;

    h += '<details class="card faq-card sc-howto"><summary><b>How gem levels work</b></summary><ul class="faq-list">' +
      '<li>A gem levels up to <b>' + max + '</b>. Levels past that come from gear and the passive tree.</li>' +
      '<li><b>Spells</b>: the hit grows <b>×' + (G.DamageGrowth || 1.19) + '</b> per gem level.</li>' +
      '<li><b>Attacks</b>: each gem level adds <b>' + Math.round((G.AttackEffectivenessPerLevel || 0) * 100) + '%</b> to the share of weapon damage the skill deals. Some skills also ramp up early or late levels.</li>' +
      '<li>The first <b>5</b> gear levels count like gem levels: spells ×' + (G.DamageGrowth || 1.19) + ', attacks <b>×' + (G.BonusLevelAttackMore || 1.06) + '</b> more each.</li>' +
      '<li>Past +5: spells and minion gems grow ×1.16, ×1.13, ×1.10, then ×1.08 a level (patch notes 6 Nov, unchanged in 0.56.7); attacks only ×1.01 a level. So stacking gear levels pays off most for spells and minions.</li>' +
      '<li>Mana cost goes up with gem level too. Each card\'s second row shows levels ' + (max + 1) + '–' + (max + 20) + '; past ' + (max + 5) + ' it is the sim\'s reading of the patch notes, not yet checked against the game.</li>' +
      '</ul></details>';

    const ORDER = ['Str', 'Dex', 'Int'], GROUP = { Str: ['red', 'Red · Strength'], Dex: ['green', 'Green · Dexterity'], Int: ['blue', 'Blue · Intelligence'] };
    const list = Object.values(GD.skills).filter(s => ORDER.includes(s.Attribute) && ['attack', 'spell'].includes(kindOf(s))).sort((a, b) => a.Name.localeCompare(b.Name));
    const ids = new Map(Object.entries(GD.skills).map(([key, s]) => [s, key]));
