    tip.innerHTML = html; tip.hidden = false;
    const r = t.getBoundingClientRect(), w = tip.offsetWidth, hg = tip.offsetHeight;
    let y = r.bottom + 6; if (y + hg > innerHeight - 8) y = Math.max(8, r.top - hg - 6);
