      if (g.hits && g.hits.length) { const h = g.hits.map(x => x.v).sort((a, b) => a - b); bits.push('boss hits logged ' + h.length + ' (median ' + h[h.length >> 1] + ', max ' + h[h.length - 1] + ', crit ' + Math.round(g.hits.filter(x => x.crit).length / h.length * 100) + '%)'); }
