  async function decodeBuildCode(text) {
    const code = String(text || '').trim().replace(/\s+/g, '');
    if (!/^BO1\./.test(code)) throw new Error('A build code starts with BO1. (copy it from the passive tree).');
    let b64 = code.slice(4).replace(/-/g, '+').replace(/_/g, '/'); while (b64.length % 4) b64 += '=';
    let bin; try { bin = atob(b64); } catch (e) { throw new Error('The code is damaged or cut short.'); }
    const bytes = Uint8Array.from(bin, c => c.charCodeAt(0));
    if (bytes.length < 8) throw new Error('The code is cut short.');
    if (typeof DecompressionStream === 'undefined') throw new Error('This browser cannot unpack build codes; try a current Chrome, Edge or Firefox.');
    const stream = new Blob([bytes.slice(4)]).stream().pipeThrough(new DecompressionStream('deflate'));
    let json; try { json = await new Response(stream).text(); } catch (e) { throw new Error('The code is damaged or cut short.'); }
    return JSON.parse(json);
  }



