    const map = Object.assign({}, st.ch.oaths || {}), o = GD.oaths[oid];
    let msg;
    if (map[mid] === oid) { delete map[mid]; msg = o.Name + ' given up.'; }
    else { if (oathBlocked(m, oid, allocSet(), swornNow())) return; map[mid] = oid; msg = o.Name + ' sworn at ' + m.Name + '.'; }
